"""
Agent session registry manager.

Manages ~/.qbraid/sessions.json - the source of truth for known agent sessions.
Follows the EnvironmentRegistryManager pattern with file locking and atomic writes.
"""

import json
import logging
import os
import sys
import tempfile
import time
import uuid
from contextlib import contextmanager
from pathlib import Path
from typing import Generator, Optional

from .constants import SERVER_INFO_FILE, SESSIONS_FILE
from .exceptions import AgentRegistryError, AgentSessionNotFoundError
from .schemas import AgentSession, AgentStatus, AgentTool, SessionRegistry

logger = logging.getLogger(__name__)


class AgentSessionRegistryManager:
    """Manages the local agent session registry at ~/.qbraid/sessions.json.

    Provides CRUD operations with file locking for cross-process safety.
    """

    def __init__(self, registry_path: Optional[str] = None):
        self._registry_path = Path(registry_path or SESSIONS_FILE)
        self._registry: Optional[SessionRegistry] = None

    @property
    def registry_path(self) -> Path:
        """Path to the registry file."""
        return self._registry_path

    @contextmanager
    def _file_lock(self) -> Generator[None, None, None]:
        """Acquire an exclusive file lock for registry operations."""
        lock_path = self._registry_path.with_suffix(".lock")
        lock_path.parent.mkdir(parents=True, exist_ok=True)

        fd = None
        try:
            fd = os.open(str(lock_path), os.O_CREAT | os.O_RDWR)
            if sys.platform == "win32":
                import msvcrt  # pylint: disable=import-outside-toplevel

                msvcrt.locking(fd, msvcrt.LK_LOCK, 1)
            else:
                import fcntl  # pylint: disable=import-outside-toplevel

                fcntl.flock(fd, fcntl.LOCK_EX)
            yield
        finally:
            if fd is not None:
                try:
                    if sys.platform == "win32":
                        import msvcrt  # pylint: disable=import-outside-toplevel

                        msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
                    else:
                        import fcntl  # pylint: disable=import-outside-toplevel

                        fcntl.flock(fd, fcntl.LOCK_UN)
                    os.close(fd)
                except OSError:
                    pass

    def load_registry(self) -> SessionRegistry:
        """Load the registry from disk.

        Returns:
            SessionRegistry with all sessions.
        """
        try:
            if self._registry_path.exists():
                with open(self._registry_path, "r", encoding="utf-8") as f:
                    data = json.load(f)

                if isinstance(data, dict):
                    raw_sessions = data.get("sessions", [])
                    sessions = []
                    for raw in raw_sessions:
                        try:
                            session = AgentSession.model_validate(raw)
                            sessions.append(session)
                        except Exception as e:
                            logger.debug("Skipping invalid session entry: %s", e)
                    self._registry = SessionRegistry(
                        sessions=sessions,
                        version=data.get("version", 1),
                    )
                else:
                    self._registry = SessionRegistry()
            else:
                self._registry = SessionRegistry()
        except (json.JSONDecodeError, OSError) as e:
            logger.warning("Could not read session registry, starting fresh: %s", e)
            # Back up the corrupted file before overwriting
            if self._registry_path.exists():
                import shutil

                backup = self._registry_path.with_suffix(".json.bak")
                try:
                    shutil.copy2(self._registry_path, backup)
                    logger.warning("Backed up corrupted registry to %s", backup)
                except OSError as backup_err:
                    logger.warning("Failed to back up corrupted registry: %s", backup_err)
            self._registry = SessionRegistry()

        return self._registry

    def save_registry(self) -> None:
        """Write the registry to disk atomically."""
        if self._registry is None:
            return

        directory = self._registry_path.parent
        directory.mkdir(parents=True, exist_ok=True)

        try:
            import warnings

            with warnings.catch_warnings():
                warnings.simplefilter("ignore", UserWarning)
                data = {
                    "version": self._registry.version,
                    "sessions": [
                        s.model_dump(mode="json", by_alias=True) for s in self._registry.sessions
                    ],
                }
            fd, tmp_path = tempfile.mkstemp(dir=str(directory), suffix=".tmp")
            try:
                with os.fdopen(fd, "w") as f:
                    json.dump(data, f, indent=2)
                os.replace(tmp_path, str(self._registry_path))
            except Exception:
                try:
                    os.unlink(tmp_path)
                except OSError:
                    pass
                raise
        except Exception as e:
            raise AgentRegistryError(f"Failed to save session registry: {e}") from e

    def register_session(self, session: AgentSession) -> str:
        """Add or update a session in the registry.

        If a session with the same pid and tool already exists and is active,
        it is updated rather than duplicated.

        Args:
            session: The session to register.

        Returns:
            The session ID of the registered session.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            if not session.session_id:
                session.session_id = str(uuid.uuid4())

            if not session.started_at:
                session.started_at = time.time()

            # Check for existing session with same session_id — update it
            for i, existing in enumerate(self._registry.sessions):
                if existing.session_id == session.session_id:
                    update_data = session.model_dump(
                        mode="json",
                        exclude={"session_id", "started_at"},
                        exclude_none=True,
                    )
                    updated = existing.model_copy(update=update_data)
                    self._registry.sessions[i] = updated
                    self.save_registry()
                    return existing.session_id

            self._registry.sessions.append(session)
            self.save_registry()
            return session.session_id

    _TOOL_MAP = {"claude": AgentTool.CLAUDE, "codeq": AgentTool.CODEQ, "codex": AgentTool.CODEX}

    def register_from_hook_payload(self, data: dict) -> Optional[str]:
        """Register an agent session from a hook payload dict.

        Handles session ID generation, tool inference from transcript paths,
        and mapping hook payload fields to an AgentSession.

        Args:
            data: Hook payload dict with fields like tool_id, pid, cwd,
                  transcript_path, source, session_id, etc.

        Returns:
            The session_id if registered, None if the tool could not be determined.
        """
        import secrets  # pylint: disable=import-outside-toplevel
        import string  # pylint: disable=import-outside-toplevel

        tool_id = data.get("tool_id", data.get("tool", ""))
        pid = data.get("pid")
        session_id = data.get("session_id", data.get("id", ""))

        # If QBRAID_SESSION_ID is set (by AgentLauncher), use it as session_id
        # so the hook merges into the launcher-created registry entry
        launcher_sid = os.environ.get("QBRAID_SESSION_ID")
        if launcher_sid:
            session_id = launcher_sid

        if not session_id:
            session_id = "".join(
                secrets.choice(string.ascii_lowercase + string.digits) for _ in range(8)
            )

        # Infer tool from payload context if not explicitly provided
        if not tool_id:
            transcript = data.get("transcript_path", "")
            source = data.get("source", "")
            if "/.claude/" in transcript or source in ("startup",):
                tool_id = "claude"
            elif "opencode" in transcript.lower():
                tool_id = "codeq"
            elif "codex" in transcript.lower():
                tool_id = "codex"

        tool = self._TOOL_MAP.get(tool_id)
        if not tool:
            return None

        # Hook processes are transient -- PID=0 sessions won't be pruned by prune_dead_sessions
        if not pid:
            pid = 0

        session = AgentSession(
            session_id=session_id,
            tool=tool,
            pid=pid,
            status=AgentStatus.IDLE,
            cwd=data.get("cwd"),
            port=data.get("port"),
            terminal_name=data.get("terminal_name"),
            model_name=data.get("model") or data.get("model_name"),
            transcript_path=data.get("transcript_path"),
            started_at=time.time(),
            last_activity=time.time(),
        )

        return self.register_session(session)

    def deregister_session(
        self,
        session_id: Optional[str] = None,
        pid: Optional[int] = None,
        tool: Optional[str] = None,
    ) -> Optional[str]:
        """Mark a session as stopped.

        Match by session_id, or by pid+tool.

        Returns:
            The session ID if found and deregistered, None otherwise.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for session in self._registry.sessions:
                if session.status in (AgentStatus.STOPPED, AgentStatus.ERROR):
                    continue

                if session_id and session.session_id == session_id:
                    session.status = AgentStatus.STOPPED
                    session.last_activity = time.time()
                    session.pid = 0  # Clear PID — it's meaningless once stopped
                    self.save_registry()
                    return session.session_id

                if pid is not None and tool and session.pid == pid and session.tool.value == tool:
                    session.status = AgentStatus.STOPPED
                    session.last_activity = time.time()
                    session.pid = 0
                    self.save_registry()
                    return session.session_id

        return None

    def get_session(self, session_id: str) -> AgentSession:
        """Get a session by ID.

        Raises:
            AgentSessionNotFoundError: If session is not found.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for session in self._registry.sessions:
                if session.session_id == session_id:
                    return session

        raise AgentSessionNotFoundError(f"Session not found: {session_id}")

    def get_active_sessions(self) -> list[AgentSession]:
        """Return all sessions that are not stopped or errored."""
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            return [
                s
                for s in self._registry.sessions
                if s.status not in (AgentStatus.STOPPED, AgentStatus.ERROR)
            ]

    def update_session(self, session_id: str, **updates) -> AgentSession:
        """Update fields on an existing session.

        Args:
            session_id: The session to update.
            **updates: Field names and new values.

        Returns:
            The updated session.

        Raises:
            AgentSessionNotFoundError: If session is not found.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for i, session in enumerate(self._registry.sessions):
                if session.session_id == session_id:
                    # Validate updates through model reconstruction
                    current_data = session.model_dump()
                    current_data.update(updates)
                    updated = AgentSession.model_validate(current_data)
                    self._registry.sessions[i] = updated
                    self.save_registry()
                    return updated

        raise AgentSessionNotFoundError(f"Session not found: {session_id}")

    @contextmanager
    def batch_update(self):
        """Context manager for batch registry modifications.

        Acquires the file lock, loads the registry, yields the
        ``SessionRegistry`` object for direct mutation, then saves
        on exit. Ensures the lock is always released, even on crash.

        Usage::

            with registry.batch_update() as reg_data:
                for session in discovered:
                    reg_data.sessions.append(session)
            # Lock released and registry saved automatically
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None
            try:
                yield self._registry
            finally:
                self.save_registry()

    # Fields that contain user-provided metadata and should be preserved during merge
    _USER_METADATA_FIELDS = {
        "tags",
        "metadata",
        "team_id",
        "role",
        "message_inbox",
        "parent_session_id",
        "child_session_ids",
    }

    def merge_discovered_sessions(self, discovered: list[AgentSession]) -> int:
        """Merge discovered sessions into the registry.

        Uses batch_update() for atomic registry modification. For each
        discovered session:
        - Skips tmux-managed sessions (lifecycle handled by launcher)
        - Preserves user metadata fields on existing entries
        - Prevents status downgrades (active -> stopped)
        - Appends new sessions not yet in the registry

        Args:
            discovered: List of sessions found by discovery scan.

        Returns:
            Count of newly added sessions.
        """
        registered_count = 0

        with self.batch_update() as reg_data:
            existing_by_id = {
                s.session_id: (i, s) for i, s in enumerate(reg_data.sessions) if s.session_id
            }

            for session in discovered:
                sid = session.session_id
                if not sid:
                    continue

                entry = existing_by_id.get(sid)
                if entry:
                    idx, existing = entry

                    # Skip tmux-managed sessions — lifecycle handled by launcher
                    if existing.tmux_session and existing.tmux_window:
                        continue

                    # Enrich existing entry, preserve user metadata
                    discovered_data = session.model_dump(exclude_none=True)
                    for field in {"session_id", "started_at", "pid"} | self._USER_METADATA_FIELDS:
                        discovered_data.pop(field, None)
                    if existing.terminal_name and not existing.terminal_name.startswith("ext-"):
                        discovered_data.pop("terminal_name", None)

                    # Don't downgrade active -> stopped
                    current_entry = reg_data.sessions[idx]
                    new_status = discovered_data.get("status")
                    cur_status = current_entry.status.value if current_entry.status else "stopped"
                    if cur_status in {"working", "waiting", "idle"} and new_status == "stopped":
                        discovered_data.pop("status", None)
                        discovered_data.pop("last_activity", None)

                    updated = current_entry.model_copy(update=discovered_data)
                    reg_data.sessions[idx] = updated
                    existing_by_id[sid] = (idx, updated)
                else:
                    reg_data.sessions.append(session)
                    existing_by_id[sid] = (len(reg_data.sessions) - 1, session)
                    registered_count += 1

        return registered_count

    def prune_dead_sessions(self) -> list[str]:
        """Check all active sessions for dead PIDs and mark them stopped.

        Returns:
            List of session IDs that were pruned.
        """
        pruned: list[str] = []
        now = time.time()

        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for session in self._registry.sessions:
                if session.status in (AgentStatus.STOPPED, AgentStatus.ERROR):
                    continue
                if session.pid <= 0:
                    continue
                try:
                    os.kill(session.pid, 0)
                except (OSError, ProcessLookupError):
                    session.status = AgentStatus.STOPPED
                    session.last_activity = now
                    session.pid = 0
                    pruned.append(session.session_id)

            if pruned:
                self.save_registry()
                logger.info("Pruned %d dead sessions from registry", len(pruned))

        return pruned

    def refresh_discovered_sessions(self, threshold_s: float = 3600, check_limit: int = 50) -> dict:
        """Refresh activity status for discovered (external) sessions.

        Two-pass approach:
        1. Mark active external sessions as stopped if inactive > threshold_s
        2. Check the most recent ``check_limit`` sessions — if their transcript
           file has recent activity, flip them back to active

        This makes ``list`` self-healing: interacting with an external agent
        causes it to appear in the next ``list`` without a full ``discover``.

        Cost: ~50 stat() calls (~1ms total).

        Args:
            threshold_s: Seconds of inactivity before marking stopped.
                Default: 3600 (1 hour).
            check_limit: Number of recent sessions to re-check for activity.

        Returns:
            Dict with ``pruned`` and ``reactivated`` session ID lists.
        """
        pruned: list[str] = []
        reactivated: list[str] = []
        now = time.time()

        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            # Pass 1: Mark stale active sessions as stopped
            for session in self._registry.sessions:
                if session.status in (AgentStatus.STOPPED, AgentStatus.ERROR):
                    continue
                # Skip tmux-managed (handled by prune_managed_sessions)
                if session.tmux_session and session.tmux_window:
                    continue
                # Skip sessions with live PIDs (handled by prune_dead_sessions)
                if session.pid and session.pid > 0:
                    continue
                # Skip remote compute sessions (can't check locally)
                if session.compute_id:
                    continue

                # Check most recent activity from all sources
                latest = session.last_activity or 0
                if session.transcript_path:
                    try:
                        mtime = Path(session.transcript_path).stat().st_mtime
                        latest = max(latest, mtime)
                    except OSError:
                        pass

                if latest and (now - latest) > threshold_s:
                    session.status = AgentStatus.STOPPED
                    session.last_activity = latest
                    pruned.append(session.session_id)

            # Pass 2: Check recent sessions for reactivation
            # Sort by transcript file mtime (not last_activity, which may be
            # stale from when the session was wrongly stopped)
            stopped_with_transcripts = [
                s
                for s in self._registry.sessions
                if s.status == AgentStatus.STOPPED
                and s.transcript_path
                and not (s.tmux_session and s.tmux_window)
                and not s.compute_id
            ]

            # Get mtime for sorting — stat each file (cheap, ~50 stat calls)
            def _get_mtime(s: AgentSession) -> float:
                try:
                    assert s.transcript_path is not None  # guaranteed by filter
                    return Path(s.transcript_path).stat().st_mtime
                except OSError:
                    return 0

            candidates = sorted(
                stopped_with_transcripts,
                key=_get_mtime,
                reverse=True,
            )[:check_limit]

            for session in candidates:
                try:
                    assert session.transcript_path is not None  # guaranteed by filter
                    mtime = Path(session.transcript_path).stat().st_mtime
                    if (now - mtime) <= threshold_s:
                        session.status = AgentStatus.IDLE
                        session.last_activity = mtime
                        reactivated.append(session.session_id)
                except OSError:
                    pass

            if pruned or reactivated:
                self.save_registry()
                if pruned:
                    logger.info("Marked %d stale sessions stopped", len(pruned))
                if reactivated:
                    logger.info("Reactivated %d sessions with recent activity", len(reactivated))

        return {"pruned": pruned, "reactivated": reactivated}

    def find_by_pid(self, pid: int) -> Optional[AgentSession]:
        """Find an active session by PID."""
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for session in self._registry.sessions:
                if session.pid == pid and session.status not in (
                    AgentStatus.STOPPED,
                    AgentStatus.ERROR,
                ):
                    return session

        return None

    def find_by_tool(self, tool: str) -> list[AgentSession]:
        """Find all active sessions for a given tool."""
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            return [
                s
                for s in self._registry.sessions
                if s.tool.value == tool and s.status not in (AgentStatus.STOPPED, AgentStatus.ERROR)
            ]

    def find_by_prefix(self, prefix: str) -> Optional[AgentSession]:
        """Find the first session whose session_id starts with the given prefix.

        Searches all sessions (including stopped/errored).

        Args:
            prefix: The session ID prefix to match.

        Returns:
            The first matching AgentSession, or None.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            for session in self._registry.sessions:
                if session.session_id.startswith(prefix):
                    return session

        return None

    def search_sessions(
        self,
        *,
        tool: Optional[str] = None,
        status: Optional[str] = None,
        tags: Optional[list[str]] = None,
        cwd_contains: Optional[str] = None,
        compute_id: Optional[str] = None,
        agent_type: Optional[str] = None,
        since: Optional[float] = None,
        text_search: Optional[str] = None,
        include_stopped: bool = False,
    ) -> list[AgentSession]:
        """Search sessions with flexible filter criteria.

        All filters are combined as AND conditions.

        Args:
            tool: Match sessions with this tool value.
            status: Match sessions with this status value.
            tags: Session must have ALL specified tags.
            cwd_contains: Case-insensitive substring match on session cwd.
            compute_id: Exact match on compute_id.
            agent_type: Exact match on agent_type.
            since: Only include sessions active or started at/after this timestamp.
            text_search: Case-insensitive substring match across terminal_name,
                cwd, and tags.
            include_stopped: If False (default), exclude STOPPED and ERROR sessions.

        Returns:
            List of matching AgentSession objects.
        """
        with self._file_lock():
            self.load_registry()
            assert self._registry is not None

            results: list[AgentSession] = []

            for session in self._registry.sessions:
                if not include_stopped and session.status in (
                    AgentStatus.STOPPED,
                    AgentStatus.ERROR,
                ):
                    continue

                if tool is not None and session.tool.value != tool:
                    continue

                if status is not None and session.status.value != status:
                    continue

                if tags is not None and not set(tags).issubset(set(session.tags)):
                    continue

                if cwd_contains is not None:
                    if not session.cwd or cwd_contains.lower() not in session.cwd.lower():
                        continue

                if compute_id is not None and session.compute_id != compute_id:
                    continue

                if agent_type is not None and session.agent_type != agent_type:
                    continue

                if since is not None:
                    activity_match = (
                        session.last_activity is not None and session.last_activity >= since
                    )
                    started_match = session.started_at is not None and session.started_at >= since
                    if not (activity_match or started_match):
                        continue

                if text_search is not None:
                    needle = text_search.lower()
                    haystack = " ".join(
                        filter(
                            None,
                            [
                                session.terminal_name,
                                session.cwd,
                                " ".join(session.tags),
                            ],
                        )
                    ).lower()
                    if needle not in haystack:
                        continue

                results.append(session)

            return results

    @staticmethod
    def write_server_info(port: int, pid: int, token: str = "") -> None:
        """Write ~/.qbraid/server.json with connection info.

        Includes the auth token so CLI hooks can authenticate their requests.
        """
        directory = os.path.dirname(SERVER_INFO_FILE)
        os.makedirs(directory, exist_ok=True)
        info = {
            "port": port,
            "pid": pid,
            "token": token,
            "started_at": time.time(),
        }
        try:
            fd, tmp_path = tempfile.mkstemp(dir=directory, suffix=".tmp")
            with os.fdopen(fd, "w") as f:
                json.dump(info, f, indent=2)
            os.replace(tmp_path, SERVER_INFO_FILE)
            logger.info("Wrote server info: port=%d pid=%d", port, pid)
        except Exception as e:
            logger.error("Error writing server info: %s", e)
